import {Kitchen} from './simulation.mjs';
import {FOODS,EQUIPMENT,STATIONS,STATION_BY_ID,WORLD,RECIPES,PREPS,METHODS,clamp,objectName,artFor,cookingLabel} from './catalog.mjs';
