 const s=STATIONS.find(s=>p.x>=s.rect[0]&&p.x<=s.rect[0]+s.rect[2]&&p.y>=s.rect[1]&&p.y<=s.rect[1]+s.rect[3])||STATIONS.find(s=>Math.hypot(p.x-s.label[0],p.y-s.label[1])<35);if(s){togglePanel(false);goStation(s.id);}
