 if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();camera.follow=false;camera.x+=(e.code==='ArrowRight'?1:e.code==='ArrowLeft'?-1:0)*35/camera.zoom;camera.y+=(e.code==='ArrowDown'?1:e.code==='ArrowUp'?-1:0)*35/camera.zoom;constrainCamera();$('#follow-btn').setAttribute('aria-pressed','false');}
