 if(selectedObject){ctx.strokeStyle='#ffd68c';ctx.lineWidth=2/camera.zoom;ctx.beginPath();ctx.ellipse(p.x,p.y,size*.54,size*.4,0,0,Math.PI*2);ctx.stroke();}
 if(!o.fixed)renderedHits.push({uid:o.uid,x:p.x,y:p.y,radius:size*.46});
