 if(game.appliances.oven.enabled&&!game.appliances.oven.door){ctx.fillStyle='#ff9c3018';rr(931,116,117,55,6);ctx.fill();}
 for(const s of STATIONS){if(camera.zoom>.48||s.id===game.station||s.id===destination)pill(s.name.toUpperCase(),...s.label,s.id===(destination||game.station));}
 ctx.fillStyle='#001e1266';ctx.beginPath();ctx.ellipse(player.x,player.y+17,24,9,0,0,Math.PI*2);ctx.fill();const bob=path.length?Math.sin(player.walk*12)*2:0;drawSprite({sheet:'original',index:15},player.x,player.y-13+bob,74,player.angle);
